source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    colors = [color for color in counts if color != background]
    color = max(colors, key=lambda value: counts[value])
    rectangles = []
    for top in range(h - 2):
        for bottom in range(top + 2, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    if (all(grid[top][c] == color for c in range(left, right + 1))
                        and all(grid[bottom][c] == color for c in range(left, right + 1))
                        and all(grid[r][left] == color and grid[r][right] == color
                                for r in range(top, bottom + 1))):
                        rectangles.append((top, bottom, left, right))
    for top, bottom, left, right in rectangles:
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                out[r][c] = 4
    return out
'''
